class Battery(val voltage: Double) {
    val isLowBattery: Boolean
        get() = voltage < 11.0
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testLowBattery() {
        val battery = Battery(10.5)
        Assert.assertTrue(battery.isLowBattery)
    }

    @Test
    fun testFullBattery() {
        val battery = Battery(12.6)
        Assert.assertFalse(battery.isLowBattery)
    }

    @Test
    fun testBoundary() {
        val battery = Battery(11.0)
        Assert.assertFalse(battery.isLowBattery)
    }

    @Test
    fun testJustBelow() {
        val battery = Battery(10.99)
        Assert.assertTrue(battery.isLowBattery)
    }
}
